def smallest_multiple_up_to(n):
    def g(a, b):
        while b:
            a, b = b, a % b
        return a
    result = 1
    for i in range(2, n + 1):
        result = result * i // g(result, i)
    return result

def is_triangular_number(n):
    import math
    if n < 0:
        return False
    k = (math.isqrt(8 * n + 1) - 1) // 2
    return k * (k + 1) // 2 == n

def sum_of_proper_divisors(n):
    n = abs(n)
    return sum(i for i in range(1, n) if n % i == 0)

def count_perfect_squares_up_to(n):
    import math
    if n < 1:
        return 0
    return math.isqrt(n)

def is_product_palindrome(a, b):
    s = str(a * b)
    return s == s[::-1]

def is_repdigit(n):
    s = str(abs(n))
    return len(set(s)) == 1

def gcd_of_digits(n):
    def g(a, b):
        while b:
            a, b = b, a % b
        return a
    digits = [int(d) for d in str(abs(n)) if d != '0']
    if not digits:
        return 0
    result = digits[0]
    for d in digits[1:]:
        result = g(result, d)
    return result

def lcm_of_digits(n):
    def g(a, b):
        while b:
            a, b = b, a % b
        return a
    digits = [int(d) for d in str(abs(n)) if d != '0']
    if not digits:
        return 0
    result = digits[0]
    for d in digits[1:]:
        result = result * d // g(result, d)
    return result

def omega_prime_factor_count(n):
    n = abs(n)
    count = 0
    d = 2
    while d * d <= n:
        while n % d == 0:
            count += 1
            n //= d
        d += 1
    if n > 1:
        count += 1
    return count

def is_prime_power(n):
    if n < 2:
        return False
    temp = n
    d = 2
    prime_found = None
    while d * d <= temp:
        if temp % d == 0:
            prime_found = d
            while temp % d == 0:
                temp //= d
            break
        d += 1
    if prime_found is None:
        return True
    return temp == 1

def next_prime(n):
    def isp(x):
        if x < 2:
            return False
        if x < 4:
            return True
        if x % 2 == 0:
            return False
        i = 3
        while i * i <= x:
            if x % i == 0:
                return False
            i += 2
        return True
    candidate = n + 1
    while not isp(candidate):
        candidate += 1
    return candidate

def previous_prime(n):
    def isp(x):
        if x < 2:
            return False
        if x < 4:
            return True
        if x % 2 == 0:
            return False
        i = 3
        while i * i <= x:
            if x % i == 0:
                return False
            i += 2
        return True
    candidate = n - 1
    while candidate >= 2 and not isp(candidate):
        candidate -= 1
